static void AdjustEquipment(Transform t,float yaw,float scale){var before=new Bounds(t.GetComponentsInChildren<Renderer>()[0].bounds.center,Vector3.zero);foreach(var r in t.GetComponentsInChildren<Renderer>())before.Encapsulate(r.bounds);t.rotation=Quaternion.Euler(0,yaw,0)*t.rotation;t.localScale*=scale;var after=new Bounds(t.GetComponentsInChildren<Renderer>()[0].bounds.center,Vector3.zero);foreach(var r in t.GetComponentsInChildren<Renderer>())after.Encapsulate(r.bounds);t.position+=new Vector3(before.center.x-after.center.x,before.min.y-after.min.y,before.center.z-after.center.z);}
static void Box(Transform parent,string name,Vector3 center,Vector3 size){var o=new GameObject(name);o.layer=parent.GetChild(0).gameObject.layer;o.transform.SetParent(parent,false);var b=o.AddComponent<BoxCollider>();b.center=center;b.size=size;}
